insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Local SEO Services","heading":"Get Found Where Your Customers Are Looking","body":"Local SEO is the work of appearing when somebody nearby searches for what you do. It runs across your Google Business Profile, your listings, your reviews and your service pages, and it is measured across your whole service area rather than as one number.","primaryCta":{"label":"View Local SEO Packages","href":"/monthly-seo-packages#local"},"showcase":[{"kind":"share","label":"A month of Citywide","title":"Where the Work Goes","unit":"tasks in a Citywide month, at the published maximums","series":[{"label":"Review replies","value":20},{"label":"Citations","value":15},{"label":"Profile posts","value":12},{"label":"Review requests","value":4}]},{"kind":"channels","label":"Three tiers","title":"Sized by Area","items":["Neighborhood","Citywide","Metro"]}]}'::jsonb, 0 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'audience-fit', 'cardGrid', 'surface', '{"variant":"cards","columns":4,"eyebrow":"Is This You","heading":"Who Local SEO Is For","body":"The first three sort by how customers reach you. The fourth is about scale, so a practice with four offices is both the third and the fourth.","cards":[{"title":"Storefront","icon":"storefront","body":"Customers come to you, and being findable on a map is most of the battle. Shops, showrooms, studios, gyms."},{"title":"Service Area","icon":"map-pin","body":"You travel to the customer, so you are ranked against an area rather than an address. Trades, contractors, mobile services."},{"title":"Appointment-Based","icon":"calendar","body":"Customers book time with you, and they compare two or three options before doing it. Practices, clinics, salons, consultants."},{"title":"Multi-Location","icon":"building","body":"Several locations competing across the same broad area. Each one needs its own profile, its own citations and its own tracking, or they compete with each other."}]}'::jsonb, 1 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'includes', 'cardGrid', 'white', '{"variant":"cards","columns":3,"eyebrow":"What You Get","heading":"What Local SEO Includes","body":"Every package includes all six. Tiers differ by volume, not by what is included.","cards":[{"title":"SEO Strategy & Roadmap","icon":"compass","body":"A plan for the next quarter rather than a list of tasks, with the reasoning behind the order it runs in."},{"title":"Content & On-Page Optimization","icon":"pencil","body":"Service pages, titles, descriptions and on-page structure written for how people in your area actually search."},{"title":"Technical Monitoring","icon":"gauge","body":"Crawling, indexing and site health watched month to month, so a problem is found before it costs you visibility."},{"title":"Detailed Monthly Reporting","icon":"bar-chart","body":"What was tracked, what moved and what did not, in language that does not need translating."},{"title":"Monthly Project Recap","icon":"message-square","body":"A person walking through the month rather than a file dropped into an inbox, with room to ask questions."},{"title":"Review Management","icon":"star","body":"Review requests sent to real customers and replies written to what comes back, positive and negative alike."}]}'::jsonb, 2 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'visibility-system', 'cardGrid', 'white', '{"variant":"cards","columns":5,"eyebrow":"The System","heading":"The Local Visibility System","body":"Five parts, worked together. Any one of them on its own tends to stall.","cards":[{"title":"Google Business Profile","icon":"storefront","body":"Categories, services, information, photos and posts. For many local searches the profile is what is being ranked.","href":"/google-business-profile-optimization"},{"title":"Citations & NAP Consistency","icon":"shield-check","body":"One standard for your name, address and phone number, applied across the listings that currently disagree with each other."},{"title":"Reviews","icon":"star","body":"Requests to real customers and replies to what arrives. Nothing fabricated, nothing incentivized."},{"title":"Local Search Grid Tracking","icon":"map-pin","body":"Visibility measured across a grid of points in your service area rather than as one blended rank, so you can see where you are strong and where you are not.","visual":"searchGrid"},{"title":"Strategic SEO Pages","icon":"file-text","body":"Pages built for the services and areas worth competing for, rather than one page trying to hold all of them."}]}'::jsonb, 3 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'houston-positioning', 'fullWidthText', 'surface', '{"eyebrow":"Houston-Area SEO","heading":"Houston-Area SEO, Based in League City","body":"JMC is based in League City and works with businesses across the Houston area."}'::jsonb, 4 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'packages', 'pricingCards', 'surface', '{"eyebrow":"Pricing","heading":"Local SEO Packages","body":"Three tiers, sized by how much ground you are competing for. Every tier includes all six of the deliverables above.","packageIds":["local-neighborhood","local-citywide","local-metro"]}'::jsonb, 5 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'custom-scope', 'fullWidthText', 'surface', '{"heading":"Working With Something Bigger?","body":"If the scope is bigger or more involved than what is here, JMC will look at it and put together a quote. However many locations are involved, a business competing in local results is still a Local engagement.","cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 6 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'sprint-callout', 'calloutBanner', 'white', '{"heading":"Or Start With a Launch Sprint","body":"The Neighborhood Launch Sprint is $799, one-time, completed within 30 days. It builds the local foundation and finishes with a 30-day roadmap. Begin monthly service within 30 days of the sprint finishing and the onboarding fee on any Local package is waived, up to $649.","primaryCta":{"label":"View Launch Sprints","href":"/launch-sprints"},"secondaryCta":{"label":"View Local SEO Packages","href":"/monthly-seo-packages#local"}}'::jsonb, 7 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"Four questions, every month, in the same order, with the written recap alongside a short video or call.","did":"The profile, listing, review, content, and technical work completed that month.","why":"Why that work was the priority for the business and its service area.","changed":"What moved across Search, Maps, and the local visibility grid, including what did not move.","next":"The next priorities in order, so the coming month starts with a clear plan.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 8 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Local SEO Questions","items":[{"question":"How long before there are results?","answer":"Local tends to move faster than national search because the competing field is smaller, and profile or listing corrections can show within weeks. Ranking movement across a service area is a longer arc, usually a few months before the shape of it is clear. Nobody can honestly give you a date, and the recap tells you which stage the work is at each month."},{"question":"Is there a contract?","answer":"Yes. Twelve months, then month to month, with 30 days written notice to end it. The term exists because the work compounds and a three-month engagement cannot show what a twelve-month one can."},{"question":"What does the onboarding fee cover?","answer":"The audit, tracking setup, the foundational on-page work and the local visibility setup: profile, categories, services, citations and the grid baseline. It is the work that has to happen once before the monthly work means anything."},{"question":"How is this different from Traditional SEO?","answer":"Local SEO is for businesses competing for customers in a defined area, however many locations they run in it. Traditional SEO is for businesses competing across multiple markets, multiple service lines, or genuinely competitive search. It is a difference in reach, not in size."},{"question":"Do you guarantee rankings?","answer":"No, and anyone who does is guessing. What is guaranteed is the scope, the reporting, and knowing exactly what was done and why."},{"question":"What is local search grid tracking?","answer":"Instead of checking your rank from one point, it checks from a grid of points across your service area. That matters because local results change street by street: you can be first near your own address and invisible four miles away, and one blended number hides that completely."},{"question":"What if the business is not in Houston?","answer":"Local SEO is not limited to the Houston area. JMC is based in League City and most clients are nearby, but the work is the same for a business competing in a defined area anywhere."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 9 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"See where the business appears across its service area today, what is holding it back, and which gaps are worth closing first before anything is bought.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 10 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Google Business Profile Optimization","heading":"Your Google Business Profile Is Doing More Work Than Your Website","body":"For most local searches the profile is what people see, read and act on, often without ever opening a website. Getting it right is the fastest visibility work available to a local business.","primaryCta":{"label":"Get a Free Visibility Audit","href":"#free-audit"},"showcase":[{"kind":"profile","label":"What gets worked","title":"The Profile Itself","items":["Categories and services","Business information","Photos and posts","Reviews and replies"]},{"kind":"channels","label":"Where it shows","title":"Local Surfaces","items":["Map results","Local search","Profile panel"]}]}'::jsonb, 0 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'what-it-affects', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"Why It Matters","heading":"What the Profile Actually Affects","body":"Three things, none of which the website controls.","cards":[{"title":"Map Results","icon":"map-pin","body":"Where the business appears when somebody searches nearby. The profile is what is being ranked in that result, not the website behind it."},{"title":"First Impressions","icon":"storefront","body":"Hours, photos, services and reviews are read directly in the results. For a lot of searches that is the whole of what someone sees before deciding."},{"title":"Direct Actions","icon":"phone","body":"Calls, direction requests and website clicks all happen from the profile itself. A weak one loses those before a visit ever starts."}]}'::jsonb, 1 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'problems', 'cardGrid', 'white', '{"variant":"compact","columns":3,"eyebrow":"Sound Familiar","heading":"Common Profile Problems","body":"Most profiles have at least two of these. Several of them take minutes to fix and have been costing visibility for years.","cards":[{"title":"Incomplete Categories","icon":"list-checks","body":"Your primary category is wrong, or the secondary ones were never set. Categories decide which searches you are eligible for at all."},{"title":"Inconsistent Information","icon":"warning","body":"Your name, address or phone number disagrees with what other listings say. Search engines notice the disagreement even when customers do not."},{"title":"No Recent Activity","icon":"calendar","body":"Your profile has not been posted to in months. An inactive profile reads as an inactive business."},{"title":"Unanswered Reviews","icon":"message-square","body":"Reviews sitting without a reply, good ones as well as bad. The reply is read by everyone who arrives afterwards."},{"title":"Missing Services","icon":"file-text","body":"Your services and products are undefined, so the profile cannot match a search for something you genuinely do."},{"title":"No Visibility Tracking","icon":"search","body":"You have no way of knowing whether any of it is working, or where in your area you are visible and where you are not."}]}'::jsonb, 2 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'free-audit', 'auditForm', NULL, '{"eyebrow":"Free Visibility Audit","heading":"Get a Free Visibility Audit","body":"A written audit of the profile, and of the site behind it, built on the same four headings as the monthly recap: what is there, why it matters, what is working and what is not, and what to do next.","covers":["Categories, services and business information","Listing consistency across the web","Profile activity, photos and reviews","Where the profile is visible across the service area"],"note":"No call required.","submitLabel":"Get a Free Visibility Audit","profileHelp":"Optional. Paste the map listing link if you have it handy.","source":"Free Visibility Audit"}'::jsonb, 3 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'what-jmc-does', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"The Work","heading":"What JMC Does to a Profile","body":"Three things once, and three things every month, on a profile you own throughout.","groupLabels":[{"at":0,"label":"One-time foundation"},{"at":3,"label":"Ongoing every month"}],"cards":[{"title":"Profile Audit","icon":"clipboard-check","body":"A full review of the profile as it stands, against how people in your area actually search for what you do."},{"title":"Category & Services Setup","icon":"list-checks","body":"Primary and secondary categories set deliberately, with services and products defined so the profile can match real searches."},{"title":"NAP & Citation Consistency","icon":"shield-check","body":"Name, address and phone standardized, then corrected across the listings that carry an older version of them."},{"title":"Ongoing Profile Posts","icon":"pencil","body":"Regular posts through the month, so the profile stays active rather than going quiet after the setup work finishes."},{"title":"Review Requests & Replies","icon":"star","body":"Requests sent to real customers and replies written to what arrives, positive and negative alike. Nothing is fabricated or incentivized."},{"title":"Local Search Grid Tracking","icon":"map-pin","body":"Visibility measured across the service area rather than as one blended number, so you can see where the profile is strong and where it is not.","visual":"searchGrid"}]}'::jsonb, 4 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'surface', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"Profile work is easy to do invisibly, which is exactly why it gets reported the same way as everything else.","did":"The posts published, the listings corrected, the reviews replied to, named individually.","why":"Why that work was the priority, and what it was expected to affect.","changed":"Grid visibility across the service area, compared with last month, including the quiet ones.","next":"What is queued for the coming month, written down before it starts.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 5 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'white', '{"eyebrow":"Questions","heading":"Profile Questions","items":[{"question":"Is this the same as Google My Business?","answer":"Yes. Google renamed Google My Business to Google Business Profile, and a lot of people still search for the old name. It is the same listing and the same work."},{"question":"Can this be done without a monthly package?","answer":"Yes. The Neighborhood Launch Sprint covers the foundation work as a one-time engagement and finishes with a 30-day roadmap, with no obligation to continue into a monthly package afterwards."},{"question":"How long before the profile improves?","answer":"Some changes show up almost immediately: corrected categories, services, hours and information can be reflected within days. Movement in map rankings is slower and depends on how competitive your area is, which is why the reporting separates the two rather than blending them."},{"question":"Who owns the profile?","answer":"You do, always. JMC requests manager access to a profile you own and never takes ownership of one. If the engagement ends, access is removed and nothing has to be handed back, because it was never held."},{"question":"Can suspended or duplicate profiles be fixed?","answer":"Duplicates can usually be merged or removed. Suspensions vary: some are caused by fixable information problems and some are not, and nobody can promise reinstatement. What JMC will do is look at the cause honestly and tell you whether it is worth pursuing."},{"question":"Does this help a business with no storefront?","answer":"Yes. A service-area business hides its address and is ranked against the area it covers, which makes categories, service definitions and listing consistency do more of the work. JMC is a service-area business itself and does not publish a street address."}],"cta":{"label":"Get a Free Visibility Audit","href":"#free-audit"}}'::jsonb, 6 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With the Profile","body":"The audit says what the profile is missing, what it is costing, and what to do about it first. It is the same four headings as the monthly recap, written before anyone has paid for anything.","primaryCta":{"label":"Get a Free Visibility Audit","href":"#free-audit"}}'::jsonb, 7 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroCentered', NULL, '{"eyebrow":"Industries","heading":"The Method Doesn''t Change With the Industry","body":"Eight sectors, one approach. What changes between them is the search language, not the work.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 0 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'grid', 'industryGrid', 'surface', '{"eyebrow":"Where JMC Works","heading":"Eight Industries, Two Kinds of Buyer","body":"The grouping below is descriptive. It says who a business sells to, and nothing about which service it needs.","groups":[{"label":"Consumer & Community","cards":[{"title":"Home Services & Trades","body":"Trades and home service businesses that get found at the moment something breaks.","icon":"wrench","href":"/industries/home-services-trades"},{"title":"Healthcare & Wellness","body":"Practices and clinics where patients choose from a short list and book an appointment.","icon":"heart-pulse","href":"/industries/healthcare-wellness"},{"title":"Hospitality & Attractions","body":"Places people plan a visit to, from an evening out to a weekend away.","icon":"utensils","href":"/industries/hospitality-attractions"},{"title":"Professional Services","body":"Firms whose clients compare a shortlist before they ever make contact.","icon":"briefcase","href":"/industries/professional-services"}]},{"label":"Industrial & B2B","cards":[{"title":"Energy & Petrochemical","body":"Suppliers and service firms selling into plants, operators and procurement teams.","icon":"lightning","href":"/industries/energy-petrochemical"},{"title":"Maritime & Logistics","body":"Port, freight and marine operators whose customers are other businesses.","icon":"ship","href":"/industries/maritime-logistics"},{"title":"Commercial Construction & Infrastructure","body":"Contractors, civil firms and suppliers working on commercial and public projects.","icon":"hard-hat","href":"/industries/commercial-construction-infrastructure"},{"title":"Aerospace & Aviation","body":"Manufacturers, service providers and suppliers in a heavily qualified supply chain.","icon":"plane","href":"/industries/aerospace-aviation"}]}],"escapeHatch":"The method doesn''t change with the industry. If yours isn''t listed, it almost certainly still applies.","cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 1 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'the-method', 'featureSplit', 'white', '{"align":"left","eyebrow":"Pillar","heading":"What Stays the Same, and What Doesn''t","body":"The work is the same regardless of sector. The same audit, the same technical foundation, the same content approach, the same reporting. What changes is the search language buyers use, how long they take to decide, and what a single lead is worth.\n\nThat consistency is deliberate. JMC brings a transferable method and clear reporting, while each client brings the technical knowledge of its market. Based in League City, the team can ground Houston-area work in local context and apply the same disciplined process to businesses competing across wider markets.","tableHeadings":["Stays the same","Varies by industry"],"tableRows":[{"cells":["Audit and technical foundation","The search language buyers actually use"]},{"cells":["On-page and content approach","How long the buying cycle runs"]},{"cells":["Reporting and recap structure","What a single lead is worth"]}],"groups":[],"cta":{"label":"View SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 2 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'surface', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 3 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'white', '{"eyebrow":"Questions","heading":"Industry Questions","items":[{"question":"Does JMC specialize in a particular industry?","answer":"JMC uses one transparent SEO method across sectors: start with how buyers search, build the right technical and content foundation, and report what changed. Its League City base provides Houston-area context, while each client''s team supplies the technical knowledge behind the details."},{"question":"What if an industry isn''t listed here?","answer":"The method still applies. The eight above are the sectors most common around the Houston area, not a list of what JMC is willing to work on. A visibility review is the fastest way to find out how the approach lands in yours."},{"question":"Which service fits?","answer":"Reach decides it, not size. A business competing for customers in a defined area is Local SEO, however many locations it runs. A business competing across markets or service lines is Traditional SEO."},{"question":"Does the industry change the price?","answer":"No. The packages are the same across every industry. Scope is what produces a custom quote, and scope is about reach and volume rather than sector."},{"question":"Does the industry change the work?","answer":"The priorities and the search language shift, sometimes a great deal. The method and the reporting do not."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 4 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 5 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Home Services & Trades","heading":"SEO for Home Services and Trades","body":"Home service searches are urgent, local, and mostly made on a phone. Getting found in that moment is a different problem from ranking for a term someone researches over two weeks. Houston-area heat and storm seasons make that timing especially important for local trades.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"coverage","label":"How buyers search","title":"Urgent and Nearby","items":["On a phone","Outside business hours","Inside a drive-time radius","Decided in minutes"]},{"kind":"coverage","label":"What it rests on","title":"Profile and Listings","items":["Map pack","Categories","Reviews"]}]}'::jsonb, 0 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"cards","columns":5,"eyebrow":"Who This Is For","heading":"The Trades This Applies To","body":"Examples of businesses that share this search pattern and buying cycle.","cards":[{"title":"HVAC & Climate Control","icon":"gauge","body":"Demand spikes with the weather, and the searches that come with it are almost always urgent. Visibility has to already be there when the heat arrives."},{"title":"Power Washing & Exterior Cleaning","icon":"storefront","body":"A seasonal, price-comparable service where the first few businesses a homeowner finds usually get the quote requests."},{"title":"Roofing & Exterior Remodeling","icon":"home","body":"High-value jobs with a longer decision than most trades, and a spike in searches after every storm."},{"title":"Electrical & Plumbing Trades","icon":"lightning","body":"A split between emergency calls and planned work, and the two are searched for in completely different language."},{"title":"Landscaping & Tree Services","icon":"wrench","body":"Recurring and one-off work side by side, usually chosen within a tight drive-time radius."}]}'::jsonb, 1 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behavior', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behavior","heading":"What Search Looks Like in the Trades","body":"Trades searches are mostly emergencies, and an emergency search behaves nothing like a considered one. Someone whose air conditioning has failed in August is on a phone, will call one of the first businesses they see, and will not open a second page of results. Storm damage does the same thing to roofing at a larger scale, and it happens with no notice.\n\nThe buying cycle is short, often minutes. That makes the map pack and the profile more valuable here than almost anywhere else, and it makes an incomplete listing an expensive problem rather than a cleanup. Competition is usually local, which is the good news: the field is the businesses inside the same drive-time radius, not every company in the state.","groups":[{"title":"Phone first, and often after hours","icon":"phone","body":"The searches that convert best arrive outside business hours and end in a tap on a phone number."},{"title":"Seasonal spikes with no warning","icon":"lightning","body":"Weather sets the calendar. Visibility has to be built before the spike, because there is no time to build it during one."},{"title":"Won or lost inside the map pack","icon":"map-pin","body":"For urgent work the profile carries more weight than the website, so the two have to agree with each other."}]}'::jsonb, 2 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'fullWidthText', 'surface', '{"eyebrow":"Where to Start","heading":"This Work Sits in Local SEO","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth.\n\nHome Services & Trades businesses compete inside a defined area, and the profile, the map pack and the reviews attached to them decide most of it. The work belongs in local search rather than spread thin across markets the business does not sell into.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}}'::jsonb, 3 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month. For a trades business the answers are about map pack position, the service area, and whether you were visible before the season turned.","did":"The work completed that month, named task by task: profile posts, service-area pages, citation corrections, and the seasonal content queued before its season rather than during it.","why":"Why that work came first, which is usually either a service about to peak or a part of the service area ranking well behind the rest of it.","changed":"Map pack position across the service area, which urgent-intent searches moved, and call volume wherever it is being tracked. Reported honestly, including the months where little moved.","next":"Next month''s priorities, with the following seasonal spike already in the plan instead of noticed once it has started.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Home Services & Trades Questions","items":[{"question":"How quickly can a trades business expect to see movement?","answer":"Local work tends to move faster than national search because the competing field is smaller, but there is no honest way to promise a date. Profile and listing corrections can show up within weeks; content and authority work is a longer arc, and the recap tells you which one you are watching each month."},{"question":"Does a service-area business without a storefront rank differently?","answer":"Yes. A service-area business hides its address and is ranked against the area it covers rather than a pin on a map, which makes the service area definition, the categories, and consistent listings do more of the work."},{"question":"Is it worth doing SEO if most work comes from referrals?","answer":"Usually. Referrals get searched for by name before anyone calls, and a weak profile or a thin website loses jobs that were already won. That is often the cheapest fix on the list."},{"question":"What should a home service business fix first: its profile or its website?","answer":"The review follows the buyer''s path. If calls are being lost in the map results, profile and listing work comes first. If the profile earns the click but the site does not explain the service or coverage, the website becomes the priority."},{"question":"How does JMC keep a trades campaign accountable?","answer":"From its League City base, JMC grounds the work in Houston-area search conditions, then documents profile, service-area and seasonal priorities in the monthly recap so each change can be checked."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Healthcare & Wellness","heading":"SEO for Healthcare and Wellness Practices","body":"Patients research before they book, and they usually stop at the first practice that looks credible and close. Visibility and reputation do the work together here. Dense Houston-area competition makes clear location and reputation signals especially important.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"growth","label":"How patients search","title":"By Symptom, Not Specialty","items":["What hurts, in plain words","Somewhere close by","Checked against reviews","Booked, or abandoned"]},{"kind":"coverage","label":"What it rests on","title":"Reputation and Access","items":["Reviews","Photos","Booking path"]}]}'::jsonb, 0 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"compact","columns":4,"eyebrow":"Who This Is For","heading":"Practices This Applies To","body":"Examples of businesses that share this search pattern and buying cycle.","cards":[{"title":"Mental & Behavioral Health Professionals","icon":"users","body":"Searched for privately and carefully, often by specialty and modality rather than by practice name."},{"title":"Private Dental & Medical Practices","icon":"heart-pulse","body":"Among the most competitive local categories anywhere, with searches split between routine care and urgent problems."},{"title":"Physical Therapy & Sports Rehab","icon":"shield-check","body":"Referral-heavy, but nearly every referral gets checked online before an appointment is made."},{"title":"Medical Spas & Wellness Clinics","icon":"star","body":"A discretionary purchase where reviews, photos and the profile carry as much weight as the website."}]}'::jsonb, 1 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behavior', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behavior","heading":"What Search Looks Like in Healthcare","body":"Patients search by symptom and by condition far more than by specialty. Somebody types what hurts, not the clinical name for the practitioner who fixes it, and the gap between those two vocabularies is where most practice websites lose traffic they should have had.\n\nThe cycle is short but not instant. A patient will usually look at two or three practices, check reviews on each, glance at photographs, and book the one that feels closest to both an answer and a location. That makes the profile, the reviews and the appointment path part of the SEO problem rather than separate from it. Competition is local and dense, particularly in dentistry, so the difference between the third and the first result is measured in booked appointments.","groups":[{"title":"Searched by symptom, not by specialty","icon":"search","body":"Content has to meet the language patients actually use before it can rank for it."},{"title":"Reviews are read before the site is","icon":"star","body":"Reputation and visibility are the same job here, which is why review support sits inside the packages."},{"title":"Booking friction undoes the ranking","icon":"calendar","body":"Being found first is worth little if the next step is a phone number and an answering machine."}]}'::jsonb, 2 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'fullWidthText', 'surface', '{"eyebrow":"Where to Start","heading":"This Work Sits in Local SEO","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth.\n\nHealthcare & Wellness businesses compete inside a defined area, and the profile, the map pack and the reviews attached to them decide most of it. The work belongs in local search rather than spread thin across markets the business does not sell into.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}}'::jsonb, 3 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month. For a practice the answers are about symptom language, reputation, and whether the booking path survives the click.","did":"The work completed that month, named task by task: condition and symptom pages, profile and review work, and fixes to the path between a search and a booked appointment.","why":"Why that work came first, which is usually a condition the practice should be found for and is not, or a step in the booking path losing people who had already chosen it.","changed":"Which symptom and condition searches moved, how the profile and reviews are tracking, and where appointment inquiries arrived from. Reported honestly, including the months where little moved.","next":"Next month''s priorities in order, so the practice is never the last to find out what is being worked on.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Healthcare & Wellness Questions","items":[{"question":"Can a practice site rank without publishing medical advice?","answer":"Yes. Most of the useful traffic comes from service, condition and location pages describing what the practice treats and how a patient starts, rather than from clinical articles that need a physician to write and review them."},{"question":"How are patient reviews handled?","answer":"Packages include review request sends and replies. Nothing is fabricated or incentivized, and no review is ever written on a practice''s behalf, which would breach both the platform rules and the positioning this agency is built on."},{"question":"Does a multi-location practice need separate pages?","answer":"Usually yes. Each location needs its own profile, its own consistent listings, and enough of its own content that the two locations are not competing with each other in the same results."},{"question":"Which search gap should a healthcare or wellness practice address first?","answer":"The first priority is the point where the patient path breaks. That may be a missing condition page, an incomplete profile, weak review signals or a booking step that loses people after they have already chosen the practice."},{"question":"How does JMC report progress for a practice?","answer":"JMC combines its League City perspective on Houston-area search with the practice''s own clinical review. The monthly recap tracks symptom and condition visibility, profile movement, reputation signals and the path to a booked appointment."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/healthcare-wellness';
